    if (bS.onRail && bS.e.g > best) { best = bS.e.g; hue = bS.e.b; }
    if (pS.onRail && max(pS.e.r, pS.e.g) > best) { best = max(pS.e.r, pS.e.g); hue = pS.e.b; }
